const menu=document.querySelector('.menu-toggle');
menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));document.querySelector('nav').classList.toggle('open',!expanded)});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){menu.setAttribute('aria-expanded','false');document.querySelector('nav').classList.remove('open')}});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===button));document.querySelectorAll('[data-category]').forEach(figure=>{figure.hidden=button.dataset.filter!=='All'&&figure.dataset.category!==button.dataset.filter})}));
const form=document.querySelector('#enquiry-form');
if(form){const type=document.querySelector('#type');const pack=document.querySelector('#package');const requested=new URLSearchParams(location.search).get('package');if([...pack.options].some(o=>o.value===requested)){pack.value=requested;type.value='Membership enquiry'}type.addEventListener('change',()=>{document.querySelector('#visit-fields').hidden=type.value!=='Visit / trial request';document.querySelector('#date').required=type.value==='Visit / trial request'});const now=new Date();now.setMinutes(now.getMinutes()-now.getTimezoneOffset());document.querySelector('#date').min=now.toISOString().slice(0,10);form.addEventListener('submit',event=>{event.preventDefault();const result=document.querySelector('#result');result.replaceChildren();const h=document.createElement('h3');h.textContent='Your enquiry preview is ready.';const p=document.createElement('p');p.textContent=`${type.value}${pack.value?' · '+pack.value:''}. In the live website, this would go to the gym team. This demo has not sent or saved your details, and no booking has been made.`;result.append(h,p);result.hidden=false;result.focus()});form.addEventListener('input',()=>{document.querySelector('#result').hidden=true})}

const bookingDialog=document.querySelector('#booking-dialog');
if(bookingDialog){const bookingForm=document.querySelector('#booking-form');const result=document.querySelector('#booking-result');document.querySelectorAll('.book-plan').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.plan').forEach(card=>card.classList.remove('is-selected'));button.closest('.plan').classList.add('is-selected');bookingForm.reset();result.hidden=true;document.querySelector('#booking-plan').value=button.dataset.plan;bookingDialog.showModal()}));document.querySelector('.booking-close').addEventListener('click',()=>bookingDialog.close());bookingDialog.addEventListener('close',()=>{bookingForm.reset();result.hidden=true;document.querySelectorAll('.plan').forEach(card=>card.classList.remove('is-selected'))});bookingForm.addEventListener('submit',event=>{event.preventDefault();result.textContent='Your '+document.querySelector('#booking-plan').value+' booking request preview is ready. This prototype has not sent or saved any details, taken payment, or confirmed a membership.';result.hidden=false;result.focus()});bookingForm.addEventListener('input',()=>{result.hidden=true})}
